export const featuresCSS = ".fx-h .a{color:var(--accent)}\n\n  .fx-wrap{max-width:1140px;margin:0 auto;padding:0 22px}\n\n  /* Section head + the tier filter. The filter is the navigation the carousel's dots\n     pretended to be: 14 unlabelled dots are not a way to find anything. */\n  /* margin-top 58, not 30. The cap has to sit BETWEEN the nav (ends 70px) and the eyebrow,\n     and at 30px that gap was 30px wide — no line fits in there without appearing to touch\n     one of them. Nudging --cy could never fix it; the gap was the problem. At 58 the\n     eyebrow starts at 128 and the cap has ~26px of clearance either side. */\n  .fx-top{text-align:center;margin:58px 0 26px}\n  .fx-eyebrow{display:inline-block;font-family:'Barlow Condensed',sans-serif;font-size:11px;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:var(--accent);background:rgba(0,230,104,.1);border:1px solid rgba(0,230,104,.25);border-radius:100px;padding:5px 13px;margin-bottom:16px}\n  .fx-h{font-family:'Barlow Condensed',sans-serif;font-size:52px;font-weight:700;line-height:1.02;letter-spacing:.004em}\n  .fx-sub{color:rgba(255,255,255,.62);font-size:15px;margin-top:13px;max-width:545px;margin-left:auto;margin-right:auto;line-height:1.6}\n  .fx-cta{display:flex;gap:10px;justify-content:center;margin-top:20px;flex-wrap:wrap}\n  .fx-btn{font-size:14px;font-weight:800;color:#04120a;background:var(--accent);border-radius:10px;padding:11px 18px;display:inline-block;transition:background .15s}\n  .fx-btn:hover{background:#12f277}\n  .fx-btn.ghost{background:transparent;color:rgba(255,255,255,.8);border:1px solid rgba(255,255,255,.16)}\n  .fx-btn.ghost:hover{color:#fff;border-color:rgba(255,255,255,.34);background:rgba(255,255,255,.04)}\n  /* \"Start free\" gets the events-page deep-dive / Climb·Pick'em look — a green-tinted panel\n     with a green border instead of a solid fill (.ftab-pick in pages.js). Applied to both\n     the hero button (.fx-btn) and the footer one (.big.ghost); the two-class selectors\n     out-specify each base rule so it wins without !important. */\n  .fx-btn.fx-cta-free, .big.ghost.fx-cta-free{background:linear-gradient(180deg,rgba(0,230,104,.09),rgba(0,230,104,.03));border:1px solid rgba(0,230,104,.35);color:#f4f5f7}\n  .fx-btn.fx-cta-free:hover, .big.ghost.fx-cta-free:hover{background:linear-gradient(180deg,rgba(0,230,104,.18),rgba(0,230,104,.07));border-color:var(--accent)}\n  .fx-trust{color:var(--muted);font-size:12px;margin-top:13px}\n  @media (max-width:560px){ .fx-h{font-size:36px} }\n\n  /* STICKY — the chips ride with you through the grid.\n     They used to scroll away with the hero, so for five screens you had no idea which\n     tier you were in or how much was left. Pinned, they answer three things at once:\n     where am I (the active chip, which spy() was already computing and had nowhere to\n     show), how much is left (the counts), and how do I get out (tap Premium, skip the\n     Free block). Costs ~46px of a 844px phone — about 5% — and buys orientation through\n     the longest part of the page.\n     The blur/background is not decoration: cards scroll UNDER this, and without an opaque\n     backing the counts sit on top of a moving preview and become unreadable. */\n  /* The heading's tier badge. One per group instead of one per card: the signifier sits\n     where the decision is — \"this whole section is Premium\" — not stapled to fifteen\n     cards that all say the same thing. Green FREE, gold PREMIUM, the palette's existing\n     two meanings and no new ones. */\n  .fx-btag{font-size:9px;font-weight:800;letter-spacing:.09em;padding:3px 8px;border-radius:999px;white-space:nowrap;flex:0 0 auto}\n  .fx-btag.free{color:var(--accent);background:rgba(0,230,104,.12);border:1px solid rgba(0,230,104,.3)}\n  .fx-btag.prem{color:#ffcf7a;background:rgba(255,207,122,.10);border:1px solid rgba(255,207,122,.3)}\n\n  .fx-fb{background:none;border:0;color:var(--muted);font-family:'Barlow Condensed',sans-serif;font-weight:700;font-size:12.5px;letter-spacing:.1em;text-transform:uppercase;padding:7px 17px;border-radius:999px;cursor:pointer;transition:color .15s,background .15s}\n  .fx-fb:hover{color:#f4f5f7}\n  .fx-fb.on{background:var(--accent);color:#0a0a0b}\n  .fx-fb .n{opacity:.6;font-size:11px;margin-left:5px}\n\n  /* Tier band — the thing the carousel could never say, because its tag changed every\n     7 seconds: here's the line, and here's which side each feature is on. */\n  /* scroll-margin-top clears the sticky bar. Without it, tapping a chip scrolls the band\n     to y=0 — directly underneath the bar that's pinned there — so the thing you asked to\n     see is the one thing hidden. */\n  .fx-band{display:flex;align-items:center;gap:13px;margin:34px 0 16px;scroll-margin-top:58px}\n  .fx-band:first-of-type{margin-top:26px}\n  .fx-bt{font-family:'Barlow Condensed',sans-serif;font-size:20px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;white-space:nowrap}\n  .fx-bt.free{color:var(--accent)}\n  .fx-bt.prem{color:#ffcf7a}\n  .fx-bn{font-size:12px;color:var(--muted);white-space:nowrap}\n  /* Each rule fades AWAY from the title — solid where it meets the words, gone at the\n     margin. That direction is the whole effect: it reads as the heading anchoring a line\n     that trails off, not as a line with a label parked on it.\n     Desktop: the left rule is hidden and the arrangement is label · badge · note · ————,\n     which is what it has always been. The explicit orders below are what let the same\n     markup become ———— · label · badge · ———— over the note on a phone. */\n  .fx-bl{flex:1;height:1px}\n  .fx-bl.l{display:none;background:linear-gradient(90deg,transparent,var(--border))}\n  .fx-bl.r{background:linear-gradient(90deg,var(--border),transparent)}\n  .fx-bt{order:1} .fx-btag{order:2} .fx-bn{order:3} .fx-bl.r{order:4}\n\n  /* 2-up from 720px, not 1000px. A 760px tablet was getting one column when two fit\n     comfortably (~350px each, and the payloads reflow down to about there).\n     BELOW 720px IT STAYS ONE COLUMN, and that is not laziness: two columns on a 390px\n     phone gives cards 174px wide, and these payloads are authored for ~580px. They would\n     not reflow into that, they'd collapse — bars, labels and avatar rows stacking into\n     rubble. Side-by-side genuinely is better, right up until the previews stop being\n     readable, at which point it's worse than the carousel. The phone gets the scroll\n     shortened instead (see the frame height below). */\n  .fx-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(340px,1fr));gap:20px;grid-auto-flow:dense}\n\n  .fx-card{background:var(--card);border:1px solid var(--border);border-radius:16px;overflow:hidden;cursor:zoom-in;transition:transform .2s cubic-bezier(.2,.7,.3,1),border-color .2s,box-shadow .2s;display:flex;flex-direction:column}\n  .fx-card:hover{transform:translateY(-4px);border-color:rgba(0,230,104,.4);box-shadow:0 14px 38px rgba(0,0,0,.5)}\n  .fx-card.prem:hover{border-color:rgba(255,207,122,.4)}\n  .fx-ch{padding:15px 17px 12px;display:flex;align-items:flex-start;gap:10px}\n  .fx-ct{font-weight:750;font-size:15.5px;line-height:1.25;letter-spacing:.005em}\n  .fx-cd{color:var(--muted);font-size:12.5px;line-height:1.5;margin-top:5px}\n  .fx-pill{font-size:9.5px;font-weight:700;letter-spacing:.07em;padding:3px 8px;border-radius:999px;white-space:nowrap;flex:0 0 auto;margin-left:auto}\n  .fx-pill.free{color:var(--accent);background:rgba(0,230,104,.12);border:1px solid rgba(0,230,104,.28)}\n  .fx-pill.prem{color:#ffcf7a;background:rgba(255,207,122,.10);border:1px solid rgba(255,207,122,.28)}\n\n  /* The preview frame.\n     NO transform:scale(). The first version pinned each payload to the carousel's\n     authored 580px and scaled it to fit the card, which is fine at 2-up on a desktop\n     and ruinous on a phone: a 375px screen gives scale(0.55), so 11px type renders at\n     6px and the previews become unreadable smudges — worse than the carousel, which is\n     the one thing this layout must not be. MEASURED: the payloads carry no hardcoded\n     width over 100px, 53 flex/grid layouts and min-widths of 50–66px, i.e. they were\n     built to reflow, and the carousel already relies on that (its stage is max-width,\n     not fixed). So let them reflow into the card exactly as they reflow into the stage:\n     readable at any width, no scaling, and one less thing to keep in sync. */\n  .fx-frame{position:relative;height:290px;overflow:hidden;background:#0d0d10;border-top:1px solid var(--border);margin-top:auto}\n  .fx-scaler{padding:16px 18px}\n\n  /* THE ONE PAYLOAD THAT DOES NOT REFLOW.\n     I removed transform:scale() from every card because the slide payloads are flex/grid\n     and reflow happily — measured: no hardcoded width over 100px. The matchup hub is the\n     exception and it is not a small one: it is authored for the modal's real\n     width:min(1040px,94vw), and .mh-grid has four fixed tracks\n     (var(--mh-rail) 1fr 1fr 1fr). It cannot reflow. Handed 520px it wraps every label and\n     squashes the tiles into rubble — which is what \"it's broken\" looked like.\n     So this card alone gets the original treatment: render at the true 1040px and scale\n     the whole thing down to fit. That is right HERE and wrong everywhere else, which is\n     why it is one class and not a global. */\n  /* THE HUB CARD SPANS THE WHOLE ROW, so it gets ~1096px and renders at ~1:1 instead of\n     the half-size thumbnail it was at 520px. It is also the headline premium feature, so\n     a full-width card is the right hierarchy anyway — this is one of those rare cases\n     where the layout fix and the design answer are the same thing. */\n  .fx-card.wide{grid-column:1 / -1}\n  .fx-card.wide .fx-scaler{width:1040px;transform-origin:top left;padding:14px 16px}\n  .fx-card.wide .fx-frame{height:360px}\n\n  /* BELOW 720px, DO NOT SCALE IT — LET IT REFLOW.\n     matchup-free.css has its own phone block: .mh-grids collapses to one column, the\n     header wraps instead of shrinking, the tabs and body tighten. That is how the real\n     modal survives a 390px screen, and it keys on VIEWPORT width — which is also why the\n     desktop card needed scaling in the first place: at a 1512px viewport the payload uses\n     its desktop layout no matter how narrow the box around it is.\n     So under 720px the media query is already doing the work; scaling on top of it would\n     shrink an already-correct layout to 35%. Hand it the card's width and get out of the\n     way — exactly what the modal does. */\n  @media (max-width:720px){\n    .fx-card.wide .fx-scaler{width:auto;transform:none !important;padding:12px 13px}\n    /* The hub keeps a taller frame than its neighbours here too: it reflows into a header,\n       tabs and two stacked grids, and 172px showed the header and nothing else — a preview\n       of a modal that never previewed the modal. Same stale 15-card tax as the rule above. */\n    .fx-card.wide .fx-frame{height:330px}\n  }\n  .fx-fade{position:absolute;left:0;right:0;bottom:0;height:96px;background:linear-gradient(180deg,rgba(13,13,16,0),rgba(13,13,16,.82) 46%,#0d0d10);pointer-events:none}\n  .fx-expand{position:absolute;right:11px;bottom:10px;font-family:'Barlow Condensed',sans-serif;font-size:11px;font-weight:700;letter-spacing:.09em;text-transform:uppercase;color:var(--muted);background:rgba(20,20,26,.9);border:1px solid var(--border);border-radius:7px;padding:5px 9px;pointer-events:none;transition:color .15s,border-color .15s}\n  .fx-card:hover .fx-expand{color:var(--accent);border-color:rgba(0,230,104,.45)}\n  .fx-card.prem:hover .fx-expand{color:#ffcf7a;border-color:rgba(255,207,122,.45)}\n\n  /* Expand = detail on demand. Nothing is HIDDEN behind it — the preview is already\n     on the card; this is just the full-size read. That's the difference between this\n     and an accordion. */\n  /* SCROLL LOCK, iOS-shaped.\n     body{overflow:hidden} does not hold on iOS Safari — it never has — so the page kept\n     scrolling behind the expanded card. The usual fix is body{position:fixed;top:-scrollY},\n     but that would be a bug here: #bgframe is absolutely positioned against BODY, so\n     making body fixed collapses its containing block to the viewport and the rails would\n     snap from full-document height to one screen, mid-interaction.\n     So: lock the ROOT instead (which modern iOS does respect), and give the lightbox\n     overscroll-behavior:contain so its own scroll doesn't chain out to the page behind it.\n     body is left completely alone, and #bgframe never notices. */\n  html.fx-locked{overflow:hidden}\n  /* opacity+visibility, NOT display:none/block, so the expand fades BOTH ways. display\n     can't transition, so the old version popped open and popped shut; visibility can, and\n     it still removes the overlay from hit-testing when hidden. The inner keeps its fxIn\n     slide, re-triggered in open() so it replays on every expand, not just the first. */\n  .fx-lb{position:fixed;inset:0;background:rgba(6,6,8,.86);backdrop-filter:blur(3px);z-index:80;opacity:0;visibility:hidden;transition:opacity .22s ease,visibility .22s ease;overflow-y:auto;overscroll-behavior:contain;-webkit-overflow-scrolling:touch;padding:40px 18px}\n  .fx-lb.on{opacity:1;visibility:visible}\n  .fx-lbin{max-width:640px;margin:0 auto;background:var(--card);border:1px solid var(--border);border-radius:18px;overflow:hidden;animation:fxIn .22s cubic-bezier(.2,.7,.3,1)}\n  /* Expanded, the hub gets the width the real modal gets — min(1040px,94vw), lifted from\n     index.html. 640px is what made it wrap on expand: I was showing a 1040px component in\n     a 640px box and reading the result as a bug in the component. */\n  .fx-lb.wide .fx-lbin{max-width:min(1040px,94vw)}\n  @keyframes fxIn{from{opacity:0;transform:translateY(10px) scale(.99)}to{opacity:1;transform:none}}\n  .fx-lbh{padding:16px 18px 13px;display:flex;align-items:flex-start;gap:10px;border-bottom:1px solid var(--border)}\n  .fx-lbstage{background:#0d0d10;padding:20px}\n  .fx-x{margin-left:auto;background:none;border:0;color:var(--muted);font-size:22px;line-height:1;cursor:pointer;padding:0 4px}\n  .fx-x:hover{color:#f4f5f7}\n  .fx-nav{display:flex;gap:8px;padding:12px 18px;border-top:1px solid var(--border)}\n  .fx-nb{flex:1;background:rgba(255,255,255,.03);border:1px solid var(--border);color:var(--muted);font-family:'Barlow Condensed',sans-serif;font-weight:700;font-size:12px;letter-spacing:.09em;text-transform:uppercase;padding:9px;border-radius:9px;cursor:pointer}\n  .fx-nb:hover{color:#f4f5f7;border-color:rgba(255,255,255,.25)}\n\n  .fx-note{max-width:1140px;margin:44px auto 0;padding:16px 22px;color:var(--muted);font-size:12px;line-height:1.65;border-top:1px solid var(--border)}\n  .fx-note b{color:#f4f5f7}\n\n  /* The matchup-hub slide's own stylesheet, from worker/matchup-free.js — the same one\n     the free /matchup page serves. Measured: 75 selectors, all .mh-/#mh-, no :root. */\n#mh-overlay { display: none; opacity: 0; transition: opacity 0.22s ease; position: fixed; inset: 0; background: rgba(0,0,0,0.86); z-index: 9200; }\n    #mh-box { --mh-rail: 3.4rem; display: none; opacity: 0; transition: opacity 0.22s ease, transform 0.22s ease; position: fixed; top: 50%; left: 50%; transform: translate(-50%,-50%); z-index: 9201; width: min(1040px, 94vw); max-height: 88vh; background: var(--card); border: 1px solid var(--border); border-radius: 12px; box-shadow: 0 24px 72px rgba(0,0,0,0.7); display: none; flex-direction: column; overflow: hidden; }\n    #mh-box.mh-on { display: flex; }\n\n    /* Header: the two men, and nothing else competing with them. */\n    .mh-hd { display: flex; align-items: center; gap: 1rem; padding: 1.1rem 1.25rem 0.9rem; border-bottom: 1px solid var(--border); background: linear-gradient(180deg, rgba(255,255,255,0.035), transparent); flex-shrink: 0; }\n    .mh-hd-f { display: flex; align-items: center; gap: 0.65rem; flex: 1; min-width: 0; cursor: pointer; }\n    .mh-hd-f.r { flex-direction: row-reverse; text-align: right; }\n    .mh-hd-f:hover .mh-hd-nm { color: var(--accent); }\n    .mh-hd-tx { min-width: 0; }\n    .mh-hd-nm { font-family: 'Barlow Condensed', sans-serif; font-weight: 700; font-size: 1.32rem; letter-spacing: 0.02em; line-height: 1.1; color: var(--text); transition: color 0.15s; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n    .mh-hd-rc { font-size: 0.72rem; color: var(--muted); font-variant-numeric: tabular-nums; margin-top: 0.1rem; }\n    .mh-hd-mid { text-align: center; flex-shrink: 0; }\n    .mh-hd-vs { font-family: 'Barlow Condensed', sans-serif; font-weight: 700; font-size: 0.9rem; letter-spacing: 0.16em; color: var(--muted); }\n    .mh-hd-sub { font-size: 0.6rem; letter-spacing: 0.1em; text-transform: uppercase; color: var(--muted); margin-top: 0.15rem; white-space: nowrap; }\n    .mh-x { margin-left: auto; align-self: center; background: none; border: none; color: var(--muted); font-size: 1.4rem; line-height: 1; cursor: pointer; padding: 0.1rem 0.45rem 0.25rem; border-radius: 4px; transition: color 0.15s, background 0.15s; }\n    .mh-x:hover { color: var(--text); background: rgba(255,255,255,0.07); }\n\n    .mh-tabs { display: flex; gap: 0; padding: 0 1.25rem; border-bottom: 1px solid var(--border); flex-shrink: 0; }\n    .mh-tab { background: none; border: none; border-bottom: 2px solid transparent; margin-bottom: -1px; color: var(--muted); font-family: 'Barlow Condensed', sans-serif; font-weight: 700; font-size: 0.92rem; letter-spacing: 0.13em; text-transform: uppercase; padding: 0.7rem 1rem; cursor: pointer; transition: color 0.15s, border-color 0.15s; }\n    .mh-tab:hover { color: var(--text); }\n    .mh-tab.on { color: var(--accent); border-bottom-color: var(--accent); }\n\n    /* Pick'em / The Climb switch — the same underline language as .mh-tab above, but\n       centred, because this one sits on a page rather than in a modal's header rail.\n       Its own class rather than reusing .mh-tab: those are sized for the modal and a\n       change there should not silently move a page-level control. */\n    .pc-tabs { display: flex; justify-content: center; gap: 0; border-bottom: 1px solid var(--border); margin: 0 0 1.4rem; }\n    .pc-tab { background: none; border: none; border-bottom: 2px solid transparent; margin-bottom: -1px; color: var(--muted); font-family: 'Barlow Condensed', sans-serif; font-weight: 700; font-size: 0.95rem; letter-spacing: 0.13em; text-transform: uppercase; padding: 0.75rem 1.5rem; cursor: pointer; transition: color 0.15s, border-color 0.15s; }\n    .pc-tab:hover { color: var(--text); }\n    .pc-tab.on { color: var(--accent); border-bottom-color: var(--accent); }\n    /* The game is a full-bleed column on its own page; inside the app it sits in the\n       page's content width, so drop its top padding and let .page own the spacing. */\n    #climb-host { display: block; }\n    #pc-view-climb[hidden] { display: none; }\n\n    .mh-body { padding: 1.1rem 1.25rem 1.35rem; overflow-y: auto; flex: 1; min-height: 0; }\n    .mh-loading { color: var(--muted); font-size: 0.82rem; text-align: center; padding: 2.5rem 0; }\n\n    /* THE READ. It states disparities; it never recommends a path. Given room to\n       breathe because it is the one piece of prose in here. */\n    /* No accent rule down the left edge. The radius goes back to all four corners:\n       0 6px 6px 0 only existed so the square side could sit flush against it. */\n    .mh-read { background: rgba(0,230,104,0.06); border-radius: 6px; padding: 0.8rem 1rem; font-size: 0.94rem; line-height: 1.55; color: var(--text); margin-bottom: 1.25rem; }\n    /* WHITE, not muted. These are the panel's structure — six of them carry the\n       whole reading order across both tabs — and at --muted (#666672) they sat\n       quieter than the numbers they introduce, so the eye had nothing to land on\n       when scrolling. The grey subtitle beside each one keeps its own colour below,\n       which is what preserves the hierarchy: title reads first, caption second. */\n    .mh-sec { font-family: 'Barlow Condensed', sans-serif; font-weight: 700; font-size: 0.82rem; letter-spacing: 0.14em; text-transform: uppercase; color: var(--text); margin: 1.4rem 0 0.7rem; padding-bottom: 0.35rem; border-bottom: 1px solid var(--border); }\n    .mh-sec:first-child { margin-top: 0; }\n    .mh-sec span { text-transform: none; letter-spacing: 0.02em; font-family: 'Barlow', sans-serif; font-weight: 400; font-size: 0.7rem; color: var(--muted); opacity: 0.75; margin-left: 0.5rem; }\n\n    /* Comparison row: bars grow OUT from the centre label, so which side is\n       longer is the whole message and you get it without reading a number. */\n    .mh-cmp { margin-bottom: 0.85rem; }\n    .mh-cmp-lbl { text-align: center; font-size: 0.62rem; letter-spacing: 0.1em; text-transform: uppercase; color: var(--muted); margin-bottom: 0.3rem; }\n    .mh-cmp-b { display: flex; align-items: center; gap: 0.6rem; }\n    .mh-cmp-v { flex: 0 0 5.5rem; font-weight: 700; font-size: 0.92rem; font-variant-numeric: tabular-nums; color: var(--text); }\n    .mh-cmp-v.r { text-align: right; }\n    .mh-cmp-v i { display: block; font-style: normal; font-weight: 400; font-size: 0.66rem; color: var(--muted); margin-top: 0.05rem; }\n    .mh-bars { flex: 1; display: flex; align-items: center; gap: 3px; min-width: 0; }\n    .mh-bar { flex: 1; height: 8px; background: rgba(255,255,255,0.05); border-radius: 3px; overflow: hidden; display: flex; position: relative; }\n    .mh-bar.l { justify-content: flex-end; }\n    .mh-bar > span { display: block; height: 100%; background: rgba(255,255,255,0.2); transition: width 0.3s ease; }\n    .mh-bar > span.w { background: var(--accent); }\n    /* Neutral: rows where bigger isn't better (share of offense is a habit, not a\n       virtue). Both sides read the same; only the LENGTHS carry the comparison. */\n    .mh-bar > span.n { background: rgba(255,255,255,0.42); }\n    /* Bad: worse than his own division's median, on a row where the number is a\n       beating (what lands on him). Only ever set by `grade`, never by `lead` — this\n       is a verdict about one man against his peers, not about the two of them. */\n    .mh-bar > span.b { background: #ff4040; }\n    .mh-bar.l > span { border-radius: 3px 0 0 3px; }\n    .mh-bar.r > span { border-radius: 0 3px 3px 0; }\n    /* The roster norm, as a tick. Context without printing a z-score at anyone. */\n    .mh-bar u { position: absolute; top: -2px; bottom: -2px; width: 1px; background: rgba(255,255,255,0.5); text-decoration: none; }\n\n    /* THE GRID — the actual point of the feature. Head accuracy at range and on\n       the ground correlate at -0.04: unrelated skills that one margin number was\n       averaging into mush. Two 3x3s, side by side, shaded by accuracy. */\n    .mh-grids { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; }\n    .mh-grid-t { font-size: 0.7rem; font-weight: 700; color: var(--text); text-align: center; margin-bottom: 0.4rem; }\n    /* --mh-rail is the row-label column (DISTANCE / CLINCH / GROUND). It is a\n       variable because TWO rules need to agree about it — the grid that creates it\n       and the legend that has to step over it. See .mh-gk. */\n    .mh-grid { display: grid; grid-template-columns: var(--mh-rail) 1fr 1fr 1fr; gap: 2px; }\n    .mh-gh { font-size: 0.58rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--muted); text-align: center; padding-bottom: 0.15rem; }\n    .mh-gr { font-size: 0.58rem; letter-spacing: 0.06em; text-transform: uppercase; color: var(--muted); display: flex; align-items: center; }\n    .mh-gc { border-radius: 4px; padding: 0.4rem 0.2rem; text-align: center; background: rgba(255,255,255,0.03); }\n    /* TEXT ON A SHADED CELL MUST NOT BE A MID-TONE. The cell background ranges from\n       near-black to a solid mid green (and mid red the other way), so anything\n       grey-ish lands on top of a colour of roughly its own lightness and vanishes —\n       var(--muted) #666672 on a 2sd-green cell was genuinely unreadable, which is\n       how \"86%\" was legible while its 44/51 underneath was not. Translucent WHITE\n       instead: it keeps the de-emphasis on the dark cells and stays readable on\n       every shade the ramp can produce. */\n    .mh-gc b { display: block; font-size: 0.86rem; font-weight: 700; font-variant-numeric: tabular-nums; color: #fff; }\n    .mh-gc i { display: block; font-style: normal; font-size: 0.58rem; color: rgba(255,255,255,0.72); font-variant-numeric: tabular-nums; margin-top: 0.1rem; }\n    /* THIN = real data, too little to rate. It still shows its rate and its sample,\n       because 16 of 17 is worth seeing — but DASHED and uncoloured, so it can never\n       be mistaken for a graded cell. Shading it would make the least reliable number\n       on the grid the loudest one. */\n    .mh-gc.thin { border: 1px dashed rgba(255,255,255,0.22); background: rgba(255,255,255,0.02) !important; padding: calc(0.4rem - 1px) calc(0.2rem - 1px); }\n    .mh-gc.thin b { color: rgba(255,255,255,0.6); font-weight: 400; }\n    .mh-gc.thin i { color: var(--muted); }\n    /* EMPTY = nothing thrown there at all. Not the same as \"too few\", and it used to\n       render identically. Nothing to read, so it recedes entirely. */\n    .mh-gc.empty { border: none; background: rgba(255,255,255,0.02) !important; padding: 0.4rem 0.2rem; }\n    .mh-gc.empty b, .mh-gc.empty i { color: rgba(255,255,255,0.18); font-weight: 400; }\n    /* TWO STACKED LINES, and the top one must not wrap. As one long flex row the\n       caption pushed \"Better\" onto its own line, orphaned from the gradient it\n       labels — the label ended up further from its scale than the sentence below\n       it. So: scale on line one, nowrap; what it's measured against on line two. */\n    /* CENTRED ON THE TILES, NOT ON THE CONTAINER — and those are 28px apart.\n       align-items:center was already centring this perfectly inside .mh-gk, which is\n       why it looked right and measured right: legend centre 720, container centre\n       720, offset 0. But the legend explains the TILES, and the tiles do not start\n       where the container does — every grid opens with a --mh-rail label column, so\n       the tile field runs 277..1219 and centres on 748. The legend sat 28px to its\n       left, pointing slightly past the thing it describes.\n       Stepping over one rail's width lands it on the tiles at both breakpoints: two\n       grids side by side on desktop and one stacked on a phone both put exactly one\n       rail to the left of the first tile. */\n    .mh-gk { padding-left: calc(var(--mh-rail) + 2px); display: flex; flex-direction: column; align-items: center; gap: 0.25rem; margin-top: 0.6rem; font-size: 0.6rem; color: var(--muted); text-align: center; }\n    .mh-gk-row { display: inline-flex; align-items: center; white-space: nowrap; }\n    .mh-gk-sub { opacity: 0.8; }\n    /* Diverging, because the question is \"is he better than normal here\", not \"how\n       close to 100% is he\" — nobody is close to 100% at head-at-range. Must track\n       the cell colours: they are red (#ff4040), so this cannot fade from orange. */\n    .mh-gk-sw { display: inline-block; width: 3.4rem; height: 7px; border-radius: 3px; background: linear-gradient(90deg, rgba(255,64,64,0.38), rgba(255,255,255,0.05), rgba(0,230,104,0.5)); vertical-align: middle; margin: 0 0.35rem; }\n    /* Mirrors .mh-gc.thin exactly, so the key looks like the thing it explains. */\n    .mh-gk-thin { display: inline-block; width: 0.85rem; height: 0.85rem; border-radius: 3px; border: 1px dashed rgba(255,255,255,0.22); background: rgba(255,255,255,0.02); vertical-align: middle; margin: 0 0.35rem 0 1.1rem; }\n\n    .mh-empty { color: var(--muted); font-size: 0.8rem; text-align: center; padding: 1.5rem 0; }\n\n    @media (max-width: 720px) {\n      #mh-box { width: 96vw; max-height: 92vh; }\n      .mh-grids { grid-template-columns: 1fr; gap: 1.25rem; }\n      .mh-cmp-v { flex: 0 0 4.2rem; font-size: 0.82rem; }\n      .mh-tabs { padding: 0 0.5rem; }\n      .mh-tab { padding: 0.7rem 0.7rem; font-size: 0.82rem; }\n      .mh-body { padding: 1rem 0.85rem 1.25rem; }\n      /* THE HEADER HAS TO WRAP, NOT SHRINK. At 390px the desktop row squeezed the\n         names to \"Dri…\" and \"Ka…\" and broke \"23-3-0\" across two lines — a header\n         that names neither fighter. So: the weight class drops to its own row and\n         gives its width back to the two men, VS goes (they're plainly opposed\n         without it), the avatars come down to 30px, and the names wrap instead of\n         truncating. A name on two lines is readable; \"Ka…\" is not. */\n      .mh-hd { flex-wrap: wrap; gap: 0.5rem; padding: 0.85rem 0.85rem 0.7rem; }\n      .mh-hd-f { flex: 1 1 0; gap: 0.45rem; }\n      .mh-hd-nm { font-size: 0.94rem; white-space: normal; overflow: visible; text-overflow: clip; overflow-wrap: anywhere; line-height: 1.15; }\n      .mh-hd-rc { font-size: 0.64rem; white-space: nowrap; }\n      .mh-hd-av > div { width: 30px !important; height: 30px !important; font-size: 0.6rem !important; }\n      .mh-hd-mid { order: 3; flex-basis: 100%; }\n      .mh-hd-vs { display: none; }\n      .mh-hd-sub { margin-top: 0; }\n    }\n/* ── MOBILE: EACH GROUP BECOMES A SWIPE ROW ──────────────────────────────────\n     Fifteen cards stacked is ~5 screens of identical rectangles — a texture the eye stops\n     reading around the fourth. Four named rows is ~2.4 screens, and the page's argument\n     becomes the TAXONOMY rather than the cards: scroll twice and you know this thing does\n     free play, pre-fight analysis, historical numbers and betting tools, whether or not\n     you swipe a single row.\n     This is NOT the carousel we removed. That was one row of sixteen with fifteen hidden\n     and no structure. Four rows of ~4 keep every heading and count on screen, so the row\n     is honest about what it's concealing — which vertical depth never is: card 12 of a\n     stack doesn't announce itself, it just never gets reached.\n     THE PEEK IS THE AFFORDANCE, and it is the whole ballgame. 86vw + gap leaves ~14% of\n     the next card showing. A row that ends flush at the screen edge looks like it ends,\n     and nobody swipes it. Do not \"tidy\" this to 100vw.\n     Desktop keeps the grid: rows are the answer to a small screen, not a better idea. */\n  @media (max-width:720px){\n    .fx-grid{\n      display:flex; grid-template-columns:none;\n      overflow-x:auto; overscroll-behavior-x:contain;\n      scroll-snap-type:x mandatory; -webkit-overflow-scrolling:touch;\n      /* NOT full-bleed. margin:0 -13px let the row clip at the screen edge, so a swiped\n         card slid straight under the frame rail sitting at 1vw. An overflow container\n         clips at its PADDING box, so the negative margin was handing cards the last 13px\n         either side — exactly where the rails live. Kept inside .fx-wrap's padding, cards\n         now vanish at 13px, clear of the rail, on both sides. The peek is unaffected: the\n         row is 364px of a 390px screen and the card is 86vw, so ~29px of the next one\n         still shows. */\n      gap:12px; padding:0 0 2px;\n      scrollbar-width:none;\n    }\n    .fx-grid::-webkit-scrollbar{display:none}\n    .fx-card{flex:0 0 86vw; scroll-snap-align:start}\n    /* the hub reflows via matchup-free.css's own phone rules, so it needs no special width */\n    .fx-card.wide{flex:0 0 86vw; grid-column:auto}\n    /* Air between groups, tight within: grouping is spacing, not lines. */\n    .fx-tier + .fx-tier{margin-top:34px}\n\n    /* THE HEADING WRAPS TO TWO LINES ON A PHONE.\n       It was one flex row — label, badge, note, gradient rule — with white-space:nowrap on\n       the note. Measured on a 390px screen: label ~110 + badge ~80 + note ~200 + 39px of\n       gaps = ~419px in 364px of room, and nowrap means the note cannot fold, so it just\n       leaves the screen. Adding the badge is what tipped it; the note was already close.\n       So: name and badge on line one, the promise on its own line beneath, and drop the\n       gradient rule — it is decoration and there is no width to spend on it. */\n    /* CENTRED, because the thing that justified the left edge is gone.\n       On desktop the heading is a row: label, badge, note, then a gradient rule running to\n       the right margin — the rule is what makes left-alignment read as deliberate, an\n       anchor with a line trailing off it. On a phone there's no width for the rule, so it\n       is display:none — leaving a left-aligned label pointing at nothing, in a column whose\n       hero above it is centred. Centre it and the page has one axis instead of two. */\n    .fx-band{flex-wrap:wrap;justify-content:center;text-align:center;gap:9px;margin:0 0 12px}\n    /* ———— label · badge ———— on line one, the promise on line two. The rules come back\n       (they were display:none) now that there are two of them and the heading is centred:\n       symmetrical, they frame it instead of pointing off one edge at nothing. */\n    .fx-bl.l{display:block;order:0}\n    .fx-bl.r{order:3}\n    .fx-bn{flex:0 0 100%;order:4;white-space:normal;line-height:1.4}\n  }\n  @media (max-width:560px){\n    .fx-h{font-size:29px}\n    /* NO HEIGHT OVERRIDE — the phone gets the same 290px preview as the desktop.\n       It was 172px, and that was a tax on a layout that no longer exists: when this was\n       one column of 15 cards, every pixel of preview height was paid FIFTEEN times, and\n       172 vs 290 was the difference between 5.7 and 7.8 screens. In rows only four\n       previews are in the vertical budget — the other eleven cost nothing, they're\n       sideways — so the same change is 2.4 vs 2.9 screens. Six-tenths of a screen for a\n       preview you can actually read, on the element that is the entire reason anyone taps.\n       One less thing diverging from desktop, too. */\n    .fx-fade{height:80px}\n    .fx-scaler{padding:12px 13px}\n    .fx-ch{padding:12px 13px 10px}\n    .fx-cd{font-size:12px}\n    .fx-wrap{padding:0 13px}\n    .fx-band{margin:26px 0 12px}\n  }\n  /* Faithful in-app component styles */\n  .statc{background:var(--card);border:1px solid var(--border);border-radius:6px;padding:.85rem .9rem}\n  .statc-l{font-size:.56rem;color:var(--muted);letter-spacing:.2em;text-transform:uppercase;margin-bottom:.35rem}\n  .statc-v{font-family:'Barlow Condensed',sans-serif;font-weight:700;font-size:1.7rem;letter-spacing:.02em;color:var(--accent);line-height:1}\n  .rrow{display:flex;align-items:center;gap:.7rem;background:var(--card);border:1px solid var(--border);border-radius:5px;padding:.5rem .8rem}\n  .rchamp{border-color:rgba(255,179,64,.35);background:linear-gradient(90deg,rgba(255,179,64,.06) 0%,var(--card) 100%)}\n  .rnum{font-family:'Barlow Condensed',sans-serif;font-weight:900;font-size:.95rem;color:var(--accent);min-width:22px;letter-spacing:.05em}\n  .rchamp .rnum{color:#ffb340}\n  .rname{font-family:'Barlow Condensed',sans-serif;font-weight:700;font-size:1rem;letter-spacing:.04em;text-transform:uppercase;flex:1;min-width:0;color:#fff;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n  .rrec{font-size:.72rem;color:var(--muted)}\n  .rmove{font-family:'Barlow Condensed',sans-serif;font-weight:700;font-size:.68rem;padding:.1rem .3rem;border-radius:3px;white-space:nowrap}\n  .rmu{color:#22c55e;background:rgba(34,197,94,.12);border:1px solid rgba(34,197,94,.3)}\n  .rmd{color:#ef4444;background:rgba(239,68,68,.10);border:1px solid rgba(239,68,68,.25)}\n  .rtag{font-family:'Barlow Condensed',sans-serif;font-size:.58rem;letter-spacing:.08em;text-transform:uppercase;color:#ffb340;border:1px solid rgba(255,179,64,.35);padding:.08rem .35rem;border-radius:2px}\n  /* Featured-fighter slide — mirrors the profile's grouped median bars. */\n  .fsx-bio{display:flex;flex-wrap:wrap;gap:1.1rem;padding:.8rem 0;border-top:1px solid var(--border);border-bottom:1px solid var(--border)}\n  .fsx-bio-k{font-size:.56rem;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}\n  .fsx-bio-v{font-family:'Barlow Condensed',sans-serif;font-weight:700;font-size:1.05rem;margin-top:.15rem;color:#ececf0}\n  .fsx-caption{font-size:.62rem;color:var(--muted);margin:.7rem 0 .1rem;display:flex;flex-wrap:wrap;gap:.3rem .8rem;align-items:center}\n  .fsx-legend{display:inline-flex;align-items:center;gap:.7rem;flex-wrap:wrap}\n  .fsx-lg{display:inline-flex;align-items:center;gap:.3rem}\n  .fsx-lg-sw{width:14px;height:6px;border-radius:2px;display:inline-block}\n  .fsx-lg-tick{width:2px;height:11px;background:#fff;display:inline-block}\n  .fsx-group{margin-top:.9rem}\n  .fsx-group-t{font-size:.58rem;letter-spacing:.18em;text-transform:uppercase;color:var(--muted);margin-bottom:.55rem}\n  .fsx-row{display:flex;align-items:center;gap:.7rem;margin-bottom:.5rem}\n  .fsx-group:last-child .fsx-row:last-child{margin-bottom:0}\n  .fsx-label{flex:0 0 140px;font-size:.74rem;color:#c9c9d0}\n  .fsx-bar{position:relative;flex:1;min-width:50px}\n  .fsx-track{height:8px;background:var(--surface2);border-radius:4px;overflow:hidden}\n  .fsx-track-empty{background:transparent}\n  .fsx-fill{height:100%;border-radius:4px}\n  .fsx-fill.good{background:var(--accent)}\n  .fsx-fill.bad{background:#c76a54}\n  .fsx-tick{position:absolute;top:-3px;bottom:-3px;width:2px;background:#fff;border-radius:1px}\n  .fsx-val{flex:0 0 46px;text-align:right;font-family:'Barlow Condensed',sans-serif;font-weight:900;font-size:1.05rem;color:#ececf0}\n  .fsx-val.good{color:var(--accent)}\n\n  /* The matchup-hub slide's styles, imported rather than restated. This is the SAME\n     stylesheet the free /matchup page serves, generated by gen-matchup-free.cjs from\n     index.html — so the slide is the real modal, not a landing-page impression of it.\n     MEASURED before dropping 12.7KB of someone else's CSS onto this page: 75 selectors,\n     every one inside the .mh-/#mh- namespace, no :root, nothing that can touch the hero,\n     the plans table or the carousel chrome. */\n  \n\n  /* THE HUB SLIDE NEEDS WHAT THE MODAL BOX GIVES IT, and it is not that box.\n     The stylesheet above hangs the modal's layout off the mh-box ID, which the slide does\n     not render — an id can only exist once and this payload lives in the carousel stage,\n     in a grid card and in the lightbox at the same time. So the slide inherited none of\n     it, and the one that matters is --mh-rail:\n         .mh-grid { grid-template-columns: var(--mh-rail) 1fr 1fr 1fr }\n     An undefined var makes that whole declaration invalid at computed-value time, so\n     grid-template-columns falls back to none, every cell becomes its own row, and the\n     colour-coded tiles stack in a single column instead of forming the 3x3. That is the\n     \"it's broken, it stacks\" — not styling, one missing custom property.\n     THE PAYLOAD IS AUTHORED FOR width:min(1040px,94vw) — the modal's real width, from\n     index.html — and it does NOT reflow: the grid has four fixed tracks. Anything\n     narrower wraps the labels and squashes the tiles, which is why it looked nothing like\n     the real modal at 520px. Consumers must give it ~1040px (see .fx-card.wide in\n     gen-showcase-proto.cjs, which scales it down bodily rather than squeezing it). */\n  .mh-slide{--mh-rail:3.4rem}\n  .fsx-val.bad{color:#c76a54}";

